patches={}
for mode,files in variants.items():
    source=out/(mode+"-source")
    patch=out/(mode+"-patch")
    patch.mkdir()
    for name,value in files.items():
        path=source/name
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(value)
    subprocess.run([str(head/"bin/javac"),"--patch-module","java.base="+str(source),
                    "-d",str(patch),*[str(p) for p in source.rglob("*.java")]],check=True)
    patches[mode]=patch
cp="jmh/core.jar:jmh/generator.jar:jmh/options.jar:jmh/math.jar"
classes=out/"classes"
classes.mkdir()
subprocess.run([str(head/"bin/javac"),"-cp",cp,"-processorpath",cp,"-d",str(classes),
                "test/micro/org/openjdk/bench/java/lang/SimdUTF.java"],check=True)
cp=str(classes)+":"+cp
os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
common=["-Xbatch","-XX:+UseSerialGC","-Xms1g","-Xmx1g","-XX:ActiveProcessorCount=2"]
import re
for mode in ("base","on","scope","peeled","combined","off","scopeOff","combinedOff"):
    variant={"scopeOff":"scope","combinedOff":"combined"}.get(mode,mode)
    java=(base if mode=="base" else head)/"bin/java"
    extra=["--patch-module=java.base="+str(patches[variant])] if variant in patches else []
    if mode in ("off","scopeOff","combinedOff"):extra.append("-XX:-UseSIMDUTFIntrinsics")
    cases=[
        ("copy","c1","utf16GetChars|utf16ToChars",["-p","size=1,31,4096"],6),
        ("latin1","c1","latin1Decode",["-p","size=16,31,4096"],3),
        ("latin1-c2","c2","latin1Decode",["-p","size=16,31,4096"],3),
        ("other","c1","utf8Decode|supplementaryDecode",["-p","size=31,4096"],4)]
    if mode in ("scope","scopeOff"):cases=[x for x in cases if x[0]!="copy"]
    if mode=="peeled":cases=[x for x in cases if x[0]=="copy"]
    if mode in ("off","combinedOff"):cases=[x for x in cases if x[0]!="other"]
    for study,tier,methods,params,expected in cases:
        flags=["-XX:TieredStopAtLevel=1"] if tier=="c1" else ["-XX:-TieredCompilation","-XX:CompileThreshold=100"]
        path=out/("-".join((mode,study))+".json")
        cmd=[str(java),"-cp",cp,"org.openjdk.jmh.Main",
             "org.openjdk.bench.java.lang.SimdUTF.("+methods+")$",*params,
             "-f","3","-wi","3","-i","4","-w","300ms","-r","300ms","-t","1","-prof","gc",
             "-jvm",str(java),"-jvmArgs"," ".join([*common,*flags,*extra]),
             "-rf","json","-rff",str(path)]
        print("LAYOUT_START",mode,study,flush=True)
        with path.with_suffix(".log").open("w")as stream:
            result=subprocess.run(cmd,stdout=stream,stderr=subprocess.STDOUT)
        if result.returncode:
            print(path.with_suffix(".log").read_text()[-15000:],flush=True)
            raise SystemExit(result.returncode)
        rows=json.loads(path.read_text());assert len(rows)==expected
        for row in rows:
            print("LAYOUT_RESULT",json.dumps({"mode":mode,"study":study,"tier":tier,
                "method":row["benchmark"].rsplit(".",1)[1],"params":row["params"],
                "ns":row["primaryMetric"]["score"],"ci":row["primaryMetric"]["scoreConfidence"],
                "bytes":row["secondaryMetrics"]["gc.alloc.rate.norm"]["score"]}),flush=True)
    if mode in ("base","on","scope","peeled","combined"):
        for classname,method in [("String","utf8"),("StringUTF16","getChars0")]:
            source=patches.get(variant)
            selected=(source/"java/lang"/(classname+".class")) if source else None
            target=str(selected) if selected and selected.is_file() else "java.lang."+classname
            raw=subprocess.check_output([str(java.with_name("javap")),"-v","-p","-c",target],text=True)
            path=out/(mode+"-"+classname+"-bytecodes.log");path.write_text(raw)
            lines=raw.splitlines()
            for index,line in enumerate(lines):
                if "private static" in line and (method+"(") in line:
                    print("LAYOUT_BYTECODE",mode,classname,json.dumps(lines[index:index+85]),flush=True)
                    break
    if mode in ("base","on","scope","peeled","combined"):
        for pattern,printed,params in [
            ("latin1Decode","java/lang/String.utf8",["-p","size=4096"]),
            ("utf16GetChars","java/lang/String.getChars",["-p","size=1"])]:
            if mode=="scope" and pattern!="latin1Decode":continue
            if mode=="peeled" and pattern!="utf16GetChars":continue
            path=out/(mode+"-"+pattern+"-code.log")
            cmd=[str(java),"-cp",cp,"org.openjdk.jmh.Main",
                 "org.openjdk.bench.java.lang.SimdUTF."+pattern+"$",*params,
                 "-f","1","-wi","1","-i","1","-w","300ms","-r","300ms",
                 "-jvm",str(java),"-jvmArgs"," ".join([*common,"-XX:TieredStopAtLevel=1",*extra,
                 "-XX:+UnlockDiagnosticVMOptions","-XX:+PrintInlining","-XX:CompileCommand=print,"+printed])]
            with path.open("w")as stream:subprocess.run(cmd,stdout=stream,stderr=subprocess.STDOUT,check=True)
            for section in path.read_text().split("Compiled method (c1)")[1:]:
                heading=section.splitlines()[0]
                if printed.rsplit(".",1)[1] not in heading or "%" in heading:continue
                main=re.search(r"main code\s+\[(0x[0-9a-f]+),\s*(0x[0-9a-f]+)\]",section)
                if main:print("LAYOUT_CODE",json.dumps({"mode":mode,"method":pattern,"heading":heading,
                    "main_bytes":int(main[2],16)-int(main[1],16),
                    "frame":re.findall(r"#\s*\[sp\+[^\n]+",section)[:1]}),flush=True)
print("LAYOUT_DIAGNOSTIC_COMPLETE_NOT_FINAL_IMAGE",flush=True)
